CREATE TABLE IF NOT EXISTS recruitment_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position_id uuid NOT NULL REFERENCES org_positions(id), candidate_id uuid REFERENCES workforce_candidates(id), full_name text NOT NULL, email text, application_status text NOT NULL DEFAULT 'received', interview_status text NOT NULL DEFAULT 'not_scheduled', assessment_status text NOT NULL DEFAULT 'not_started', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hiring_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position_id uuid NOT NULL REFERENCES org_positions(id), candidate_id uuid REFERENCES workforce_candidates(id), application_id uuid REFERENCES recruitment_applications(id), decision text NOT NULL DEFAULT 'pending', approved_by text, approval_notes text, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS appointment_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hiring_approval_id uuid NOT NULL REFERENCES hiring_approvals(id), employee_id uuid REFERENCES workforce_employees(id), appointment_title text NOT NULL, appointment_type text NOT NULL DEFAULT 'employment', appointment_status text NOT NULL DEFAULT 'draft', proposed_start_date date, issued_at timestamptz, accepted_at timestamptz, terms_summary text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS onboarding_checklists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES workforce_employees(id), item text NOT NULL, category text NOT NULL DEFAULT 'general', required boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'pending', completed_at timestamptz, UNIQUE(employee_id,item));
CREATE INDEX IF NOT EXISTS idx_recruitment_position_status ON recruitment_applications(position_id,application_status);
CREATE INDEX IF NOT EXISTS idx_hiring_approval_decision ON hiring_approvals(decision);
CREATE INDEX IF NOT EXISTS idx_appointment_status ON appointment_records(appointment_status);
CREATE INDEX IF NOT EXISTS idx_onboarding_employee ON onboarding_checklists(employee_id,status);